  [8, lead("4 ~ 5 ~ ~ 6 ~ ~ 5 ~ 4 ~ ~ ~ 2 ~", "~ ~ 3 ~ 4 ~ 5 ~ ~ ~ 7 ~ ~ ~ 6 ~", "5 ~ ~ 4 ~ ~ 2 ~ ~ 3 ~ 4 ~ ~ ~ ~", "~ ~ 2 ~ ~ ~ 0 ~ 1 ~ ~ ~ 2 ~ ~ ~")],
  [8, lead("0 ~ ~ 4 [3 2] ~ 1 ~ 0 ~ ~ ~ ~ ~ ~ ~", "~ ~ 2 ~ 1 ~ 0 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
